#include "prop_physics.hpp"
#include <stdexcept>
#include <iostream>
using namespace ofo;
void need(bool v,const char*m){if(!v)throw std::runtime_error(m);}
void stacked_support(){
 btDefaultCollisionConfiguration c;btCollisionDispatcher d(&c);btDbvtBroadphase b;btSequentialImpulseConstraintSolver solver;ContactWorld w(&d,&b,&solver,&c);w.setGravity({0,-9.81f,0});
 PropDefinition base;base.mass=40;base.half={.5f,.5f,.5f};base.inertia={7,7,7};base.transform=translate({0,.5f,0});auto top=base;top.transform=translate({0,1.5f,0});PropPhysics props(w,{base,top});btStaticPlaneShape floor_shape({0,1,0},0);btRigidBody::btRigidBodyConstructionInfo fi(0,nullptr,&floor_shape);btRigidBody floor(fi);w.addRigidBody(&floor,1,16);
 btSphereShape shape(.5f);btVector3 inertia;shape.calculateLocalInertia(100,inertia);btRigidBody::btRigidBodyConstructionInfo ci(100,nullptr,&shape,inertia);btRigidBody actor(ci);btTransform at;at.setIdentity();
 for(float y:{.5f,1.5f}){at.setOrigin({-.99f,y,0});actor.setWorldTransform(at);actor.setLinearVelocity({3,0,0});w.addRigidBody(&actor,2,4|16);w.performDiscreteCollisionDetection();need(props.activate_contacts(&actor,nullptr),"stack object activates from actual impact");w.removeRigidBody(&actor);}
 for(int i=0;i<600&&props.released();i++){w.stepSimulation(.01f,0);props.update_rest(.01f);}need(props.released()==0,"two-level prop stack settles to static");auto replay=props.snapshot();need(replay->size()==2,"static stack keeps both moved overrides");
 at.setOrigin({-.99f,.5f,0});actor.setWorldTransform(at);actor.setLinearVelocity({4,0,0});w.addRigidBody(&actor,2,4|16);w.performDiscreteCollisionDetection();need(props.activate_contacts(&actor,nullptr),"new impact wakes supporting prop");need(props.released()==2&&props.diagnostics()["support_loss_wakes"].get<int>()>=1,"waking base also wakes its frozen supported prop");w.removeRigidBody(&actor);
 btRigidBody*bottom=nullptr;for(int i=0;i<w.getNumCollisionObjects();i++){auto*r=btRigidBody::upcast(w.getCollisionObjectArray()[i]);if(r&&r->getInvMass()>0&&r->getWorldTransform().getOrigin().y()<1)bottom=r;}need(bottom,"dynamic base exists");auto shifted=bottom->getWorldTransform();shifted.setOrigin({5,.5f,0});bottom->setWorldTransform(shifted);w.updateSingleAabb(bottom);
 for(int i=0;i<130;i++){w.stepSimulation(.01f,0);props.update_rest(.01f);}need(props.pose(1)[13]<1,"upper object falls when supporting prop moves away");need(replay->at(1).transform[13]>1,"old frozen replay pose remains immutable");w.removeRigidBody(&floor);
}
int main(){try{stacked_support();
 btDefaultCollisionConfiguration cfg;btCollisionDispatcher dispatcher(&cfg);btDbvtBroadphase broad;btSequentialImpulseConstraintSolver solver;ContactWorld world(&dispatcher,&broad,&solver,&cfg);world.setGravity({0,0,0});
 PropDefinition def;def.bonus={2,47,.006f};def.mass=40;def.half={.5f,.5f,.5f};def.inertia={7,7,7};def.transform=translate({0,2,0});PropPhysics props(world,{def});
 btSphereShape shape(.5f);btVector3 inertia;shape.calculateLocalInertia(100,inertia);btRigidBody::btRigidBodyConstructionInfo ci(100,nullptr,&shape,inertia);btRigidBody actor(ci);btTransform at;at.setIdentity();at.setOrigin({-.99f,2,0});actor.setWorldTransform(at);world.addRigidBody(&actor,2,4|16);world.performDiscreteCollisionDetection();
 need(!props.activate_contacts(&actor,nullptr),"stationary penetrating car contact must not release a held prop");
 actor.setLinearVelocity({0,0,5});world.performDiscreteCollisionDetection();need(!props.activate_contacts(&actor,nullptr),"tangential sliding without incoming normal impulse does not release prop");
 actor.setLinearVelocity({.05f,0,0});world.performDiscreteCollisionDetection();need(!props.activate_contacts(&actor,nullptr),"minor normal jitter stays below release impulse threshold");
 actor.setLinearVelocity({3,0,0});world.performDiscreteCollisionDetection();need(props.activate_contacts(&actor,nullptr),"real normal impact releases prop");need(props.released()==1,"one dynamically active object");world.removeRigidBody(&actor);
 btRigidBody*body=nullptr;for(int i=0;i<world.getNumCollisionObjects();i++){auto*r=btRigidBody::upcast(world.getCollisionObjectArray()[i]);if(r&&r->getInvMass()>0)body=r;}need(body,"released prop rigid body exists");
 auto reward=props.claim_bonus(body);need(reward&&reward->cents==47,"first qualified claim consumes the authored reward");
 need(!props.claim_bonus(body),"same rigid instance cannot be claimed twice");
 auto moved=body->getWorldTransform();moved.setOrigin({4,2,0});body->setWorldTransform(moved);world.updateSingleAabb(body);body->setLinearVelocity({0,0,0});body->setAngularVelocity({0,1,0});
 for(int i=0;i<100;i++){world.stepSimulation(.01f,0);props.update_rest(.01f);}need(props.released()==1,"zero linear speed does not freeze a rotating object");
 body->setAngularVelocity({0,0,0});body->setLinearVelocity({0,0,0});auto resting=props.pose(0);auto before=props.snapshot();for(int i=0;i<50;i++){world.stepSimulation(.01f,0);props.update_rest(.01f);}need(props.released()==1,"short quiet interval does not prematurely freeze object");for(int i=0;i<30;i++){world.stepSimulation(.01f,0);props.update_rest(.01f);}need(props.released()==0&&body->getInvMass()==0&&body->isStaticObject(),"settled object becomes actual zero-mass static body");need(props.pose(0)==resting,"freezing preserves exact current pose");auto frozen=props.snapshot();need(frozen->size()==1&&frozen->at(0).transform==resting,"frozen moved object remains in renderer/replay overrides");for(int i=0;i<50;i++){world.stepSimulation(.01f,0);props.update_rest(.01f);}need(props.snapshot()==frozen,"stationary frozen snapshot reuses immutable storage");need(before->at(0).transform==resting,"prior replay snapshot remains intact");
 at.setOrigin(body->getWorldTransform().getOrigin()+btVector3(-.99f,0,0));actor.setWorldTransform(at);actor.setLinearVelocity({0,0,0});world.addRigidBody(&actor,2,4|16);world.performDiscreteCollisionDetection();need(!props.activate_contacts(&actor,nullptr),"resting car cannot wake settled prop");actor.setLinearVelocity({3,0,0});world.performDiscreteCollisionDetection();need(props.activate_contacts(&actor,nullptr),"new sufficient impact reactivates settled prop");need(props.released()==1&&std::abs(1/body->getInvMass()-40)<.001f,"reactivation restores authored mass");need(props.snapshot()->size()==1,"reactivation does not duplicate render override");
 need(!props.claim_bonus(body),"reactivating a settled prop cannot reissue the reward");need(props.diagnostics()["static_returns"]==1&&props.diagnostics()["reactivations"]==1,"rest/rewake diagnostics count transitions");world.removeRigidBody(&actor);
 // Under gravity, an unsupported object at zero velocity must not freeze in air.
 world.setGravity({0,-9.81f,0});body->setLinearVelocity({0,0,0});body->setAngularVelocity({0,0,0});for(int i=0;i<20;i++)props.update_rest(.1f);need(props.released()==1,"unsupported stationary object remains dynamic under gravity");
 btBoxShape platform_shape({10,.25f,10});btVector3 pi;platform_shape.calculateLocalInertia(1000,pi);btRigidBody::btRigidBodyConstructionInfo platform_info(1000,nullptr,&platform_shape,pi);btRigidBody platform(platform_info);platform.setLinearFactor({0,0,0});platform.setAngularFactor({0,0,0});platform.setActivationState(DISABLE_DEACTIVATION);world.addRigidBody(&platform,2,16);moved=body->getWorldTransform();moved.setOrigin({4,.9f,0});body->setWorldTransform(moved);world.updateSingleAabb(body);for(int i=0;i<300;i++){world.stepSimulation(.01f,0);props.update_rest(.01f);}need(props.released()==1,"prop resting on a movable car/platform stays dynamically supported");float platform_y=props.pose(0)[13];world.removeRigidBody(&platform);body->activate(true);for(int i=0;i<100;i++){world.stepSimulation(.01f,0);props.update_rest(.01f);}need(props.pose(0)[13]<platform_y-.3f,"removing movable support cannot leave prop suspended");body->setLinearVelocity({0,0,0});
 btStaticPlaneShape ground_shape({0,1,0},0);btRigidBody::btRigidBodyConstructionInfo floor_info(0,nullptr,&ground_shape);btRigidBody floor(floor_info);world.addRigidBody(&floor,1,16);moved=body->getWorldTransform();moved.setOrigin({4,.8f,0});body->setWorldTransform(moved);world.updateSingleAabb(body);body->applyCentralImpulse({10,0,0});for(int i=0;i<600&&props.released();i++){world.stepSimulation(.01f,0);props.update_rest(.01f);}need(props.released()==0,"real grounded body settles and freezes under gravity");need(props.pose(0)[13]>.35f&&props.pose(0)[13]<.8f,"grounded frozen object stays on track");world.removeRigidBody(&floor);
 std::cout<<"impulse-gated prop contact passed\n";
 }catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 1;}}
